const esc = v => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function markdown(value){
  const inline=text=>esc(text)
    .replace(/`([^`]+)`/g,'<code>$1</code>')
    .replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>')
    .replace(/\*([^*]+)\*/g,'<em>$1</em>')
    .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>');
  const lines=String(value??'').replace(/\r/g,'').split('\n'),out=[];let list='',code=false,codeLines=[];
  const closeList=()=>{if(list){out.push(`</${list}>`);list='';}};
  for(const line of lines){
    if(line.trim().startsWith('```')){closeList();if(code){out.push(`<pre><code>${esc(codeLines.join('\n'))}</code></pre>`);codeLines=[];}code=!code;continue;}
    if(code){codeLines.push(line);continue;}
    const heading=line.match(/^(#{1,3})\s+(.+)$/),bullet=line.match(/^\s*[-*]\s+(.+)$/),ordered=line.match(/^\s*\d+[.)]\s+(.+)$/);
    if(heading){closeList();out.push(`<h${heading[1].length}>${inline(heading[2])}</h${heading[1].length}>`);continue;}
    if(bullet||ordered){const next=bullet?'ul':'ol';if(list!==next){closeList();list=next;out.push(`<${list}>`);}out.push(`<li>${inline((bullet||ordered)[1])}</li>`);continue;}
    closeList();out.push(line.trim()?`<p>${inline(line)}</p>`:'<br>');
  }
  closeList();if(codeLines.length)out.push(`<pre><code>${esc(codeLines.join('\n'))}</code></pre>`);return out.join('');
}
const num = n => Number(n||0).toLocaleString('zh-TW');
const time = v => v ? new Date(v).toLocaleString('zh-TW',{hour12:false}) : '尚無資料';
const badge = code => `<span class="badge a${Number(code)}">${esc(labels[code]||'未知')}</span>`;
const detector = r => {
  const sources = Array.isArray(r.detector_sources) ? r.detector_sources.map(String)
    : (r.detector_sources ? String(r.detector_sources).split(/[,+|]/).map(s=>s.trim().toLowerCase()) : []);
  if (!sources.length) sources.push(r.origin === 'modsecurity-crs' ? 'waf' : 'ml');
  const hasWaf = sources.some(s=>s.includes('waf')||s.includes('crs'));
  const hasMl = sources.some(s=>s==='ml'||s.includes('machine'));
  if (hasWaf && hasMl) return '<span class="detector both">WAF + ML</span>';
  return hasWaf ? '<span class="detector waf">WAF / CRS</span>' : '<span class="detector ml">ML</span>';
};
const empty = (title,text) => `<div class="empty"><strong>${esc(title)}</strong>${esc(text)}</div>`;
