  if(form.dataset.user){data.enabled=form.elements.enabled.checked;await api('/users/'+form.dataset.user,{method:'PUT',body:JSON.stringify(data)});toast('使用者設定已更新');await render();}
  if(form.id==='account-form'){if(data.new_password!==data.confirm_password)throw new Error('兩次輸入的新密碼不一致');delete data.confirm_password;const result=await api('/auth/account',{method:'PUT',body:JSON.stringify(data)});if(result.signed_out){showLogin();toast('密碼已更新，請重新登入');}else{currentUser=await api('/auth/me');await startSession();toast('個人資料已更新');}}
  if(form.id==='system-settings-form'){const out={webhook:{},proxy:{}};for(const [key,value] of Object.entries(data)){const [group,name]=key.split('.');out[group][name]=value;}out.webhook.listen_port=Number(out.webhook.listen_port);for(const k of ['apache_port','flask_port','django_port'])out.proxy[k]=Number(out.proxy[k]);out.webhook.auto_register=form.elements['webhook.auto_register'].checked;out.proxy.enabled=form.elements['proxy.enabled'].checked;await api('/settings',{method:'PUT',body:JSON.stringify(out)});toast('系統設定已儲存');await render();}
